<template>
 <view class="skin-page" :class="{'plan-mode':view==='plan','landing-mode':view==='landing','analysis-mode':view==='analysis'}" :style="{'--skin-top':statusTop+'px','--staff-switch-height':staffModeVisible?'44px':'0px'}">
  <view class="skin-header" :class="{'header-home':view==='landing'}">
   <button v-if="view!=='landing'" role="button" class="back-button" aria-label="返回" @click="back"><image src="/static/skincare/back.svg" mode="aspectFit"/></button>
   <view class="wordmark"><text>HELUOJIA</text><text class="wordmark-cn">赫洛嘉</text></view>
  </view>

  <view v-if="view==='landing'" class="landing-shell">
  <StaffModeSwitch ref="staffSwitch" @visibility="staffModeVisible=$event"/>
  <view class="skin-landing">
   <view class="hero-carousel-wrap">
    <swiper class="hero-carousel" :current="heroIndex" :autoplay="pageActive&&view==='landing'" :interval="4500" :duration="500" circular @change="heroIndex=$event.detail.current" aria-label="赫洛嘉护肤主题轮播">
     <swiper-item v-for="slide in heroSlides" :key="slide.id">
      <view class="hero-slide">
       <view class="landing-heading"><text class="eyebrow">{{slide.eyebrow}}</text><text class="landing-title">{{slide.title}} <text class="marker">{{slide.accent}}</text></text><text class="landing-subtitle">{{slide.subtitle}}</text></view>
       <image v-if="!slide.journey" class="hero-art" :src="slide.image" :aria-label="slide.alt" mode="aspectFill"/>
       <view v-else class="hero-journey"><view class="journey-line"/><view v-for="(item,i) in journey" :key="item.title" class="journey-item"><view class="journey-symbol"><image :src="icon(item.icon)" mode="aspectFit"/><text>0{{i+1}}</text></view><view><text>{{item.title}}</text><text>{{item.note}}</text></view></view><image class="journey-products" src="/static/skincare/hero-creams.jpg" mode="aspectFill"/></view>
      </view>
     </swiper-item>
    </swiper>
    <view class="hero-pagination"><button v-for="(slide,index) in heroSlides" :key="slide.id" role="button" :aria-label="'切换到第 '+(index+1)+' 张：'+slide.title+slide.accent" :aria-pressed="heroIndex===index" :class="{current:heroIndex===index}" @click="heroIndex=index"><view/></button></view>
   </view>
   <view class="landing-actions"><button role="button" class="skin-button primary" @click="start">{{hasDraft?'继续我的定制':'开启我的护肤定制'}}</button><button role="button" v-if="report" class="text-button saved-link" @click="setView('report')">查看上次的护理方案 →</button></view>
  </view>
  </view>

  <view v-else-if="view==='quiz'" class="quiz-page">
   <view class="quiz-progress"><text><text class="step-number">{{step}}</text> / {{questionCount}}</text><text class="quiz-section">了解你，才能为你而选</text></view>
   <view v-if="step===1" class="question-body">
    <text class="page-title">您的性别？</text><view class="gender-options"><button role="button" v-for="gender in genders" :key="gender.id" :aria-label="gender.label" :aria-pressed="answers.gender===gender.id" :class="{selected:answers.gender===gender.id}" @click="answers.gender=gender.id;changed()"><view><image :src="icon(gender.icon)" mode="aspectFit"/></view><text>{{gender.label}}</text></button></view><button role="button" class="gender-skip" :class="{selected:answers.gender==='unspecified'}" :aria-pressed="answers.gender==='unspecified'" @click="answers.gender='unspecified';changed()">暂不填写</button>
   </view>
   <view v-else-if="step===2" class="question-body age-body">
    <text class="page-title">您的年龄？</text><text class="body-note">选填，仅用于记录这份个人护理偏好</text>
    <view class="age-field"><input v-model="answers.age" type="number" inputmode="numeric" maxlength="3" placeholder="请输入你的年龄" placeholder-class="skin-placeholder" aria-label="年龄（选填）" :adjust-position="true" @input="changed"/><text>岁</text></view>
    <text class="age-hint">不想填写也没关系，直接点击下一题。</text>
   </view>
   <view v-else-if="step===3" class="question-body">
    <text class="page-title">您当下最关注的护理目标是？</text><text class="body-note">建议选择 1–3 项</text>
    <view class="goal-grid"><button role="button" v-for="goal in goals" :key="goal.id" :aria-label="goal.label" :aria-pressed="answers.goals.includes(goal.id)" class="goal-option" :class="{selected:answers.goals.includes(goal.id)}" @click="toggleGoal(goal.id)"><view class="goal-icon"><image :src="icon(goal.icon)" mode="aspectFit"/><text v-if="answers.goals.includes(goal.id)" class="goal-check">✓</text></view><text>{{goal.label}}</text></button></view>
   <text class="selection-count">已选择 {{answers.goals.length}} / 3 项</text>
   </view>
   <view v-else-if="step===4" class="question-body followup-body"><text class="page-title">4. 平时的肤感，更接近哪一种？</text><text class="body-note">围绕{{selectedDraftGoals}}，继续了解你的日常</text><view class="survey-options"><button role="button" v-for="(feel,i) in feels" :key="feel.id" :aria-label="feel.label+'，'+feel.hint" :aria-pressed="answers.skin===feel.id" :class="{selected:answers.skin===feel.id}" @click="chooseFeel(feel.id)"><view class="answer-dot"/><text>{{optionLetter(i)}}、{{feel.label}}，{{feel.hint}}</text></button></view></view>
   <view v-else-if="currentQuestion" class="question-body followup-body"><text class="page-title">{{step}}. {{currentQuestion.title}}</text><text class="body-note">{{currentQuestion.multiple?'可多选，按日常习惯填写':'请选择最接近自己的一项'}}</text><view class="survey-options" :class="{'compact-options':currentQuestion.options.length>5}"><button role="button" v-for="(option,i) in currentQuestion.options" :key="option.id" :aria-label="option.label" :aria-pressed="responseSelected(option.id)" :class="{selected:responseSelected(option.id)}" @click="chooseResponse(option.id)"><view class="answer-dot"/><text>{{optionLetter(i)}}、{{option.label}}</text></button></view></view>
   <text v-if="formError" class="form-error" role="alert">{{formError}}</text>
   <view class="question-actions"><button role="button" class="skin-button secondary" @click="restartQuiz">重新测试</button><button v-if="step>1" role="button" class="skin-button secondary" @click="previous">上一题</button><button role="button" class="skin-button primary" @click="next">下一题</button></view>
  </view>

  <view v-else-if="view==='name'" class="name-page">
   <view class="name-heading"><text class="page-title">填写称呼，生成专属方案</text><text class="body-note">这个称呼会显示在你的护理报告中</text></view>
   <view class="paper-wrap"><view class="paper-back"/><view class="name-paper"><view class="paper-top"><view class="paper-brand">HELUOJIA<text>赫洛嘉 · 专属护肤方案</text></view><view class="paper-date"><text>{{today.day}}</text><text>{{today.month}}</text></view></view><text class="hello">Hello,</text><input v-model="answers.name" class="name-input" maxlength="20" placeholder="你希望我们如何称呼你" placeholder-class="skin-placeholder" aria-label="你的称呼" @input="changed"/><view class="paper-bottom"><text>一点了解，一份用心。</text><text>A RITUAL, JUST FOR YOU.</text></view></view></view>
   <text v-if="formError" class="form-error" role="alert">{{formError}}</text>
   <view class="name-actions"><text class="quiet">偏好报告保存在本机，可随时清除</text><button role="button" class="skin-button primary" :disabled="generating" @click="generate">{{generating?'正在整理方案…':'生成我的护肤方案'}}</button><button role="button" class="text-button" :disabled="generating" @click="setView('quiz')">返回修改偏好</button></view>
  </view>

  <SkincareAnalyzing v-else-if="view==='analysis'" :name="answers.name" :ready="analysisReady" :error="catalogError" :loading="catalogLoading" :count="recommendations.length" @report="setView('report')" @retry="loadCatalog"/>

  <view v-else-if="view==='report'&&!report" class="empty-page"><image src="/static/skincare/report.svg" mode="aspectFit"/><text class="page-title">你的专属报告，从了解开始</text><text class="body-note">完成定制问卷，在这里查看护理偏好和商品方案。</text><button role="button" class="skin-button primary" @click="start">开始填写问卷</button></view>

  <view v-else-if="view==='report'&&report" class="report-page">
   <text class="eyebrow">YOUR PERSONAL SKINCARE</text><text class="report-title">我的护肤分析报告</text><text class="report-date">{{reportDate}} · 赫洛嘉</text>
   <view class="report-card overview-card"><view class="report-greeting"><view><text class="greeting">Hi, {{report.answers.name}}</text><text class="body-note">{{analysis.headline}}</text></view><image src="/static/skincare/spark.svg" mode="aspectFit"/></view><view class="report-chart"><view class="preference-ring" :style="{background:ringBackground}"><view class="ring-center"><text>{{reportGoals.length.toString().padStart(2,'0')}}</text><text>项护理偏好</text></view></view><view class="chart-legend"><view v-for="(goal,i) in reportGoals" :key="goal.id"><text class="legend-dot" :style="{background:chartColors[i]}"/><text>{{goal.label}}</text></view></view></view><view class="profile-line"><text>日常肤感 <text>{{feelLabel}}</text></text><text>{{report.answers.age?report.answers.age+' 岁':'年龄未填写'}}</text></view></view>
   <text class="chart-explanation">圆环展示你选择的护理目标，不代表皮肤检测分数。</text>
   <SkincareInsights :analysis="analysis"/>
   <view class="report-card focus-card"><text class="card-title">逐项看看，你在意的护理目标</text><view class="focus-grid"><button role="button" v-for="goal in reportGoals" :key="goal.id" class="focus-item" @click="selectReportGoal(goal.id,true)"><view class="focus-icon"><image :src="icon(goal.icon)" mode="aspectFit"/></view><text class="focus-title">{{goal.label}}</text><text class="focus-caption">查看解读 ›</text></button></view></view>
   <view v-if="surveySummary.length" class="report-card habit-card"><text class="card-title">你的日常护理档案</text><view class="habit-highlights"><view v-for="row in surveyHighlights" :key="row.id"><text>{{row.label}}</text><text>{{row.answer}}</text></view></view><view v-if="careNotes.length" class="care-notes"><text v-for="note in careNotes" :key="note">{{note}}</text></view><button role="button" class="survey-details-toggle" :aria-expanded="surveyDetailsOpen" @click="surveyDetailsOpen=!surveyDetailsOpen">{{surveyDetailsOpen?'收起问卷记录 ⌃':'查看全部问卷记录 ⌄'}}</button><view v-if="surveyDetailsOpen" class="survey-records"><view v-for="row in surveySummary" :key="row.id"><text>{{row.question}}</text><text>{{row.answer}}</text></view></view></view>
   <view id="preference-analysis" class="preference-analysis">
    <view class="report-topic-tabs"><button role="button" v-for="goal in reportGoals" :key="goal.id" :class="{active:activeGoal.id===goal.id}" @click="selectReportGoal(goal.id)">{{goal.label}}</button></view>
    <view class="analysis-section"><view class="numbered-heading"><text>01</text><text>从你的选择，了解护理方向</text></view><view class="analysis-visual"><view><text>{{activeGuide.title}}</text><text>{{activeGuide.subtitle}}</text></view><image :src="'/static/skincare/'+activeGuide.image+'.jpg'" mode="aspectFill"/><view class="analysis-keywords"><text v-for="word in activeGuide.keywords" :key="word">{{word}}</text></view></view><text class="analysis-intro">{{activeAnalysis.lead}}</text><view class="topic-evidence"><text v-for="item in activeAnalysis.evidence" :key="item">{{item}}</text></view></view>
    <view class="analysis-section"><view class="numbered-heading"><text>02</text><text>把偏好，变成自己的日常</text></view><view class="analysis-switch"><button role="button" :class="{active:guideTab==='texture'}" @click="guideTab='texture'">质地选择</button><button role="button" :class="{active:guideTab==='routine'}" @click="guideTab='routine'">搭配思路</button></view><view class="guide-text">{{activeAnalysis[guideTab]}}</view><view class="analysis-explainer"><text class="explainer-label">{{activeGoal.label}} · 你的护理笔记</text><text class="explainer-title">让选择，更贴近你的习惯</text><text class="body-note" :class="{'clamped-note':!guideExpanded}">{{activeAnalysis.next}} {{activeGuide.more}}</text><button role="button" class="expand-guide" :aria-expanded="guideExpanded" @click="guideExpanded=!guideExpanded">{{guideExpanded?'收起内容 ⌃':'展开更多 ⌄'}}</button></view></view>
    <view class="analysis-section"><view class="numbered-heading"><text>03</text><text>这些单品，可以进一步了解</text></view><view class="report-product-row"><button role="button" v-for="product in goalRecommendations.slice(0,2)" :key="product.id" @click="openProduct(product)"><image :src="asset(product.image,640)" mode="aspectFit"/><text>{{product.name}}</text><text>{{product.spec||product.role}} · 查看商品 ›</text></button></view><button v-if="!goalRecommendations.length" role="button" class="skin-button secondary" @click="home('category')">查看当前商城单品</button></view>
   </view>
   <view class="report-footnote"><text>这是一份基于自填偏好的选购参考，不包含皮肤检测或诊断。</text><view><button role="button" class="text-button" @click="editReport">重新填写</button><button role="button" class="text-button" @click="clearReport">清除本机记录</button></view></view>
   <view class="floating-actions report-actions"><button role="button" class="skin-button secondary" @click="copyReport">复制偏好</button><button role="button" class="skin-button primary" @click="setView('plan')">查看我的方案 <text>→</text></button></view>
  </view>

  <view v-else-if="view==='plan'&&report" class="plan-page">
   <text class="report-title"><text class="marker">专属护理方案</text></text><text class="body-note">{{report.answers.name}}，根据你的偏好，认识适合日常的选择</text>
   <swiper class="plan-carousel" :autoplay="pageActive&&view==='plan'&&!consultationOpen" :interval="4500" :duration="500" circular indicator-dots indicator-color="#b3b8ba" indicator-active-color="#73afcb"><swiper-item v-for="slide in photoSlides" :key="slide.id"><view class="plan-banner"><image :src="slide.image" mode="aspectFill"/><view><text class="two-lines">{{slide.id==='daily'?'水润有序\n自在养肤':'清润 · 中润 · 倍润\n找到喜欢的质地'}}</text><text>HELUOJIA DAILY RITUAL</text></view></view></swiper-item></swiper>
   <view class="plan-summary"><view><text>为你整理<image src="/static/skincare/bottle.svg" mode="aspectFit"/></text><text>{{catalogError?'待加载':recommendations.length+' 款可选单品'}}</text></view><view><text>护理偏好<image src="/static/skincare/spark.svg" mode="aspectFit"/></text><text>{{reportGoals.map(g=>g.label).join(' · ')}}</text></view></view>
   <view class="plan-rationale"><text>{{analysis.headline}}</text><text>{{analysis.findings[1].text}}</text><text v-if="overBudgetCount" class="plan-budget-alert">有 {{overBudgetCount}} 款高于你的单品预算，可只了解需要的单品。</text></view>
   <view v-if="catalogLoading&&!products.length" class="catalog-state"><text>正在加载商城商品…</text></view>
   <view v-else-if="catalogError" class="catalog-state"><text>{{catalogError}}</text><button role="button" class="skin-button secondary" @click="loadCatalog">重新加载商品</button></view>
   <view v-else-if="!recommendations.length" class="catalog-state"><text>暂时没有可匹配的在售单品</text><text class="body-note">可以先逛逛商城，或让客服帮你了解商品。</text><button role="button" class="skin-button secondary" @click="home('category')">查看商城商品</button></view>
   <view v-else class="report-card products-card"><view class="card-heading"><text class="card-title">你的日常护理清单</text><text>按需选择</text></view><view class="recommendation-grid"><button role="button" v-for="(product,i) in recommendations" :key="product.id" class="recommendation" @click="openProduct(product)"><view class="recommendation-image"><image :src="asset(product.image)" mode="aspectFit"/><text class="product-step">0{{i+1}} / {{product.role}}</text></view><text class="recommendation-name">{{product.name}}</text><text class="recommendation-note">{{product.reason}}</text><view class="product-context"><text v-if="product.owned">{{product.ownership}}</text><text :class="{over:product.budgetMatch.status==='above'}">{{product.budgetMatch.label}}</text></view><view class="recommendation-price"><text>¥ {{money(product.price)}}</text><text>查看 ›</text></view><text v-if="product.priceLabel" class="price-note">{{product.priceLabel}}</text></button></view><text class="products-note">可以只选需要的单品。用法以产品包装说明为准，价格及可购状态以商品页为准。</text></view>
   <view v-if="recommendations.length" class="complete-plan"><text class="section-title"><text class="marker">完整护理提案</text></text><text class="body-note">从一款到一套，按自己的日常习惯选择</text><view v-for="(product,i) in recommendations" :key="product.id" class="product-editorial"><view class="editorial-heading"><text class="editorial-number">0{{i+1}}</text><view><text>{{product.role}}</text><text>{{product.name}}</text></view></view><view class="editorial-photo"><image :src="asset(product.image,960)" mode="aspectFill"/><text v-if="product.spec" class="editorial-texture">{{product.spec}}<text>质地选择</text></text></view><view class="editorial-copy"><text class="editorial-name"><text class="marker">{{product.name}}</text></text><text>{{product.detail||product.reason}}</text><button role="button" @click="openProduct(product)"><text>查看商品详情</text><text>¥ {{money(product.price)}}　↗</text></button></view></view></view>
   <view class="plan-brand"><text class="eyebrow">GET TO KNOW HELUOJIA</text><text class="section-title">让护肤，回到自己的日常</text><image src="/static/skincare/hero-creams.jpg" mode="aspectFill"/><view class="brand-principle"><text>01</text><view><text>从肤感出发</text><text>臻颜新肌系列涵盖精华水、凝润乳与面霜。清润、中润、倍润，让润泽程度有更多选择。</text></view></view><view class="brand-principle"><text>02</text><view><text>给选择一点空间</text><text>了解单品，再决定搭配。你可以从一款开始，也可以向商城客服咨询自己在意的使用体验。</text></view></view></view>
   <view class="plan-faq"><text class="section-title">你可能还想了解</text><view v-for="(faq,i) in faqs" :key="faq.question" class="faq-item"><button role="button" :aria-expanded="faqOpen===i" @click="faqOpen=faqOpen===i?-1:i"><text>{{faq.question}}</text><text>{{faqOpen===i?'−':'+'}}</text></button><text v-if="faqOpen===i">{{faq.answer}}</text></view></view>
   <view class="plan-help"><text class="card-title">想先了解，再作选择？</text><text class="body-note">留下联系方式，向商城客服咨询产品与体验活动。</text><text class="quiet">体验安排、费用及库存，由客服与你确认。</text></view>
   <button role="button" class="text-button back-report" @click="setView('report')">← 返回我的偏好报告</button>
   <view class="floating-actions"><button role="button" class="skin-button primary" @click="openConsultation">咨询专属产品体验 <text class="button-arrow">↗</text></button></view>
  </view>

  <MainTabbar v-if="!['plan','analysis'].includes(view)" active="skincare" :cart-quantity="cartQuantity" @reselect="setView('landing')"/>

  <view v-if="consultationOpen" class="consult-overlay" @click="closeConsultation" @touchmove.stop.prevent>
   <scroll-view class="consult-scroll" scroll-y @click.stop @touchmove.stop>
    <view class="consult-dialog" role="dialog" aria-modal="true" aria-label="咨询专属产品体验">
     <template v-if="consultationSent"><view class="success-symbol">✓</view><text class="modal-title">你的咨询已发送</text><text class="body-note">商城客服已收到你的联系方式和护理偏好。你也可以在「帮助与客服」的商城留言中查看回复。</text><button role="button" class="skin-button primary" @click="openSupport">查看商城留言</button><button role="button" class="text-button" @click="closeConsultation">回到我的方案</button></template>
     <template v-else><text class="modal-kicker">A LITTLE MORE PERSONAL</text><text class="modal-title">聊聊你的<text class="marker">护肤体验</text></text><text class="body-note modal-note">留下联系方式，由商城客服与你沟通</text>
      <view class="contact-field"><image src="/static/skincare/smile.svg" mode="aspectFit"/><input v-model="contact.name" maxlength="30" placeholder="你的姓名或称呼" aria-label="咨询姓名或称呼" placeholder-class="skin-placeholder" :disabled="sending||uncertain" @input="contactError=''"/></view>
      <view class="contact-field"><image src="/static/skincare/phone.svg" mode="aspectFit"/><input v-model="contact.phone" type="number" maxlength="11" placeholder="你的手机号码" aria-label="咨询手机号码" placeholder-class="skin-placeholder" :disabled="sending||uncertain" @input="contactError=''"/></view>
      <view class="contact-field"><image src="/static/skincare/pin.svg" mode="aspectFit"/><input v-model="contact.city" maxlength="60" placeholder="你所在的城市" aria-label="咨询所在城市" placeholder-class="skin-placeholder" :disabled="sending||uncertain" @input="contactError=''"/></view>
      <button role="button" class="consent-line" :disabled="sending||uncertain" :aria-pressed="contact.consent" @click="contact.consent=!contact.consent;contactError=''"><view :class="{checked:contact.consent}"><text v-if="contact.consent">✓</text></view><text>同意将以上联系方式和护理偏好发送给商城客服，仅用于本次咨询。</text></button>
      <text v-if="contactError" class="form-error" role="alert">{{contactError}}</text><text v-if="uncertain" class="retry-note">发送结果暂未确认，再次提交会核对同一条留言。</text>
      <view class="modal-actions"><button role="button" class="skin-button secondary" :disabled="sending" @click="closeConsultation">{{uncertain?'稍后处理':'取消'}}</button><button role="button" class="skin-button primary" :disabled="sending" @click="sendConsultation">{{sending?'提交中…':uncertain?'再次提交':'提交咨询'}}</button></view>
     </template>
    </view>
   </scroll-view>
  </view>
  <CopyFallback :value="copyFallback" @close="copyFallback=''" @retry="copyReport"/>
 </view>
</template>

<script>
import {request,asset,money,go,home,getToken,notify} from '../../services/shop.js'
import {copyText} from '../../services/clipboard.js'
import {captureReferral} from '../../services/referral.js'
import {pageShare} from '../../services/share.js'
import CopyFallback from '../../components/CopyFallback.vue'
import MainTabbar from '../../components/MainTabbar.vue'
import StaffModeSwitch from '../../components/StaffModeSwitch.vue'
import {checkLaunchEntry} from '../../services/staff-entry.js'
import SkincareAnalyzing from '../../components/SkincareAnalyzing.vue'
import SkincareInsights from '../../components/SkincareInsights.vue'
import {analyzeSkincare,skincareProductContext} from '../../services/skincare-analysis.js'
import {SKINCARE_GUIDES,SKINCARE_FAQS} from '../../services/skincare-content.js'
import {SKINCARE_GENDERS,SKINCARE_FOLLOWUPS,blankSkincareSurvey,asSkincareSurvey,skincareQuestionCount,toggleSkincareResponse,skincareSurveySummary,skincareCareNotes} from '../../services/skincare-survey.js'
import {SKIN_FEELS,SKIN_GOALS,normalizeSkincareAnswers,skincareStepError,createSkincareReport,restoreSkincareReport,skincareOwner,skincareStorageKey,selectedSkincareGoals,skinFeelLabel,skincareRecommendations,skincareContactError,skincareConsultationBody,skincareReportText} from '../../services/skincare.js'

const HERO_SLIDES=[
 {id:'daily',eyebrow:'YOUR SKIN. YOUR RITUAL.',title:'了解肤感',accent:'为你而选',subtitle:'让日常护肤，多一份恰到好处',image:'/static/skincare/hero.jpg',alt:'赫洛嘉精华水、面霜与臻萃油'},
 {id:'cream',eyebrow:'FIND YOUR EVERYDAY COMFORT.',title:'三种润泽',accent:'随心选择',subtitle:'清润 · 中润 · 倍润，找到喜欢的质地',image:'/static/skincare/hero-creams.jpg',alt:'赫洛嘉清透霜、柔护霜与奢润霜'},
 {id:'journey',eyebrow:'A RITUAL, JUST FOR YOU.',title:'了解自己',accent:'为你定制',subtitle:'从护理偏好，到自己的产品方案',journey:true}
]

export default {
 components:{StaffModeSwitch,CopyFallback,MainTabbar,SkincareAnalyzing,SkincareInsights},
 data(){return{staffModeVisible:false,analysisReady:false,analysisSequence:0,surveyDetailsOpen:false,cartQuantity:0,launchEntryChecked:false,reportGoalId:'',guideTab:'texture',guideExpanded:false,faqOpen:-1,view:'landing',heroIndex:0,heroSlides:HERO_SLIDES,pageActive:true,step:1,statusTop:0,answers:blankSkincareSurvey(),report:null,owner:'',hasDraft:false,formError:'',generating:false,products:[],catalogLoading:false,catalogError:'',catalogSequence:0,feels:SKIN_FEELS,goals:SKIN_GOALS,chartColors:['#5c9fc1','#a9d5e8','#d6ebf5'],consultationOpen:false,consultationSent:false,contact:{name:'',phone:'',city:'',consent:false},contactError:'',sending:false,uncertain:false,contactAttempt:null,copyFallback:'',pendingView:'',disposed:false}},
 computed:{
  analysis(){return analyzeSkincare(this.report?.answers||{})},
  activeAnalysis(){return this.analysis.topics.find(item=>item.id===this.activeGoal.id)||{}},
  overBudgetCount(){return this.recommendations.filter(p=>p.budgetMatch.status==='above').length},
  genders(){return SKINCARE_GENDERS},
  questionCount(){return skincareQuestionCount(this.answers)},
  currentQuestion(){return this.step>=5?SKINCARE_FOLLOWUPS[this.step-5]:null},
  selectedDraftGoals(){return selectedSkincareGoals(this.answers).map(g=>g.label).join('、')},
  surveySummary(){return skincareSurveySummary(this.report?.answers)},
  surveyHighlights(){return[{id:'routine',label:'在用产品'},{id:'steps',label:'步骤偏好'},{id:'budget',label:'单品预算'},{id:'service',label:'想了解的内容'}].map(item=>({...item,answer:this.surveySummary.find(r=>r.id===item.id)?.answer||''})).filter(item=>item.answer)},
  careNotes(){return skincareCareNotes(this.report?.answers)},
  photoSlides(){return this.heroSlides.filter(s=>!s.journey)},
  journey(){return[{title:'了解你的日常肤感',short:'日常肤感',note:'从自己的感受出发',icon:'care'},{title:'记录在意的护理体验',short:'护理偏好',note:'选择 1–3 项偏好',icon:'report'},{title:'查看专属护理提案',short:'专属方案',note:'认识单品，按需搭配',icon:'bottle'}]},
  faqs(){return SKINCARE_FAQS},
  activeGoal(){return this.reportGoals.find(g=>g.id===this.reportGoalId)||this.reportGoals[0]||this.goals[0]},
  activeGuide(){return SKINCARE_GUIDES[this.activeGoal.id]},
  goalRecommendations(){const preferred=['light','soft','season','night'].includes(this.activeGoal.id)?'cream':this.activeGoal.id==='radiance'?'oil':this.activeGoal.id==='makeup'?'emulsion':'toner';return [...this.recommendations].sort((a,b)=>Number(b.product_code?.toLowerCase().includes(preferred))-Number(a.product_code?.toLowerCase().includes(preferred)))},
  today(){const d=new Date();return{day:String(d.getDate()).padStart(2,'0'),month:d.getFullYear()+'/'+String(d.getMonth()+1).padStart(2,'0')}},
  reportDate(){return this.report?this.report.createdAt.slice(0,10):''},
  reportGoals(){return selectedSkincareGoals(this.report?.answers)},
  feelLabel(){return skinFeelLabel(this.report?.answers)},
  recommendations(){return skincareRecommendations(this.products,this.report?.answers).map(product=>skincareProductContext(product,this.report?.answers))},
  ringBackground(){const n=this.reportGoals.length||1;return 'conic-gradient('+this.chartColors.slice(0,n).map((c,i)=>c+' '+(i*100/n)+'% '+((i+1)*100/n-.8)+'%, #fff '+((i+1)*100/n-.8)+'% '+((i+1)*100/n)+'%').join(',')+')'}
 },
 onLoad(query){captureReferral(query?.referrer);try{this.statusTop=uni.getSystemInfoSync().statusBarHeight||0}catch{}this.pendingView=['report','plan'].includes(query?.section)?query.section:'';this.restoreState()},
 onShow(){this.pageActive=true;this.restoreState();this.refreshCartQuantity();if(!this.generating)this.loadCatalog();this.checkStaffEntry();
  // #ifdef MP-WEIXIN
  uni.showShareMenu({menus:['shareAppMessage']})
  // #endif
 },
 onHide(){this.pageActive=false},
 onUnload(){this.pageActive=false;this.disposed=true;this.catalogSequence++;this.analysisSequence++},
 onShareAppMessage(){const publicShare=pageShare('index'),query=publicShare.path.split('?')[1];return{title:'赫洛嘉 · 发现你的专属护肤方案',path:'/pages/skincare/index'+(query?'?'+query:''),imageUrl:'/static/skincare/hero.jpg'}},
 onBackPress(){if(this.consultationOpen){this.closeConsultation();return true}if(this.view!=='landing'){this.back();return true}return false},
 methods:{
   refreshCartQuantity(){const owner=getToken()?uni.getStorageSync('shop-owner'):'guest',items=uni.getStorageSync('shop-cart-'+owner+'-C');this.cartQuantity=Array.isArray(items)?items.reduce((sum,item)=>sum+(Number(item.quantity)||0),0):0},
   async checkStaffEntry(){if(this.launchEntryChecked)return;this.launchEntryChecked=true;const token=getToken();if(!token)return;try{const member=await request('/me');if(token!==getToken()||!this.pageActive||this.disposed||this.view!=='landing')return;await checkLaunchEntry(member)}catch{}},
  asset,money,go,home,icon(name){return '/static/skincare/'+name+'.svg'},
  restoreState(){
   const nextOwner=skincareOwner(getToken(),uni.getStorageSync('shop-owner'))
   if(this.owner===nextOwner)return
   this.analysisSequence++;this.generating=false;this.analysisReady=false;this.owner=nextOwner;this.products=[];this.consultationOpen=false;this.consultationSent=false;this.sending=false;this.uncertain=false;this.contactAttempt=null;this.contact={name:'',phone:'',city:'',consent:false};this.copyFallback=''
   let saved;try{saved=uni.getStorageSync(skincareStorageKey(nextOwner))}catch{}
   this.report=restoreSkincareReport(saved?.report);this.answers=asSkincareSurvey(normalizeSkincareAnswers(saved?.draft||this.report?.answers||{}));this.hasDraft=!!saved?.draft;this.step=saved?.draft?.questionnaireVersion===2&&Number.isInteger(saved?.step)?Math.max(1,Math.min(this.questionCount,saved.step)):1
   this.view=this.pendingView&&this.report?this.pendingView:'landing';this.pendingView='';this.formError=''
   if(!getToken()&&nextOwner==='guest')return
   // A one-use draft handed off by this page before login, never from a previous account.
   const handoff=uni.getStorageSync('shop-skincare-login-handoff')
   uni.removeStorageSync('shop-skincare-login-handoff')
   if(handoff&&Date.now()-Number(handoff.at)<15*60*1000&&Date.now()>=Number(handoff.at)){
    const report=restoreSkincareReport(handoff.report)
    if(report){this.report=report;this.answers=asSkincareSurvey(report.answers);this.hasDraft=false;this.view='plan';this.persist();this.consultationOpen=true;this.contact.name=report.answers.name}
   }
  },
  persist(){try{uni.setStorageSync(skincareStorageKey(this.owner),{report:this.report,draft:this.hasDraft?this.answers:null,step:this.step})}catch{notify('本机存储不可用，离开页面后可能需要重新填写')}},
  changed(){this.hasDraft=true;this.formError='';this.persist()},
  chooseFeel(id){this.answers.skin=id;this.changed()},
  optionLetter(index){return String.fromCharCode(65+index)},
  responseSelected(id){const value=this.answers.responses?.[this.currentQuestion?.id];return Array.isArray(value)?value.includes(id):value===id},
  chooseResponse(id){this.answers=toggleSkincareResponse(this.answers,this.currentQuestion.id,id);this.changed()},
  toggleGoal(id){if(this.answers.goals.includes(id))this.answers.goals=this.answers.goals.filter(g=>g!==id);else if(this.answers.goals.length<3)this.answers.goals=[...this.answers.goals,id];else{this.formError='最多选择 3 项，可以先取消已选项';return}this.changed()},
  setView(view){this.view=view;this.formError='';this.$nextTick(()=>uni.pageScrollTo({scrollTop:0,duration:0}))},
  start(){this.beginQuiz()},
  beginQuiz(){if(!this.hasDraft){this.answers=this.report?asSkincareSurvey(this.report.answers):blankSkincareSurvey();this.step=1}this.hasDraft=true;this.persist();this.setView('quiz')},
  restartQuiz(){uni.showModal({title:'重新填写问卷',content:'本次未提交的选择会被清空，已经生成的护理报告会保留。',confirmText:'重新开始',success:r=>{if(!r.confirm)return;this.answers=blankSkincareSurvey();this.step=1;this.hasDraft=true;this.persist();this.setView('quiz')}})},
  selectReportGoal(id,scroll=false){this.reportGoalId=id;this.guideExpanded=false;this.guideTab='texture';if(scroll)this.$nextTick(()=>uni.createSelectorQuery().in(this).select('#preference-analysis').boundingClientRect().selectViewport().scrollOffset().exec(rows=>{if(rows[0]&&rows[1])uni.pageScrollTo({scrollTop:Math.max(0,rows[0].top+rows[1].scrollTop-this.statusTop-58),duration:250})}))},
  previous(){if(this.step>1){this.step--;this.persist();this.setView('quiz')}else this.setView('landing')},
  next(){this.formError=skincareStepError(this.answers,this.step);if(this.formError)return;if(this.step<this.questionCount){this.step++;this.persist();this.setView('quiz')}else this.setView('name')},
  async generate(){
   if(this.generating)return
   let candidate;try{candidate=createSkincareReport(this.answers);analyzeSkincare(candidate.answers)}catch(e){this.formError=e.message;return}
   const seq=++this.analysisSequence,owner=this.owner,token=getToken()
   this.generating=true;this.analysisReady=false;this.persist();this.setView('analysis')
   await this.loadCatalog()
   if(seq!==this.analysisSequence||this.disposed||this.owner!==owner)return
   if(getToken()!==token){this.generating=false;this.setView('name');this.formError='登录状态已变更，请重新生成方案';return}
   this.report=candidate;this.reportGoalId=candidate.answers.goals[0];this.surveyDetailsOpen=false;this.hasDraft=false;this.persist();this.generating=false;this.analysisReady=true
  },
  editReport(){this.answers=asSkincareSurvey(this.report.answers);this.step=1;this.hasDraft=true;this.persist();this.setView('quiz')},
  clearReport(){uni.showModal({title:'清除本机护理记录',content:'本机保存的问卷和报告会被清除。已发送给客服的留言仍可在商城留言中查看。',confirmText:'确认清除',success:r=>{if(!r.confirm)return;uni.removeStorageSync(skincareStorageKey(this.owner));uni.removeStorageSync('shop-skincare-login-handoff');this.report=null;this.answers=blankSkincareSurvey();this.hasDraft=false;this.step=1;this.contactAttempt=null;this.uncertain=false;this.contact={name:'',phone:'',city:'',consent:false};this.setView('report')}})},
  back(){if(this.consultationOpen)return this.closeConsultation();if(this.view==='analysis'){if(this.analysisReady)return this.setView('report');this.analysisSequence++;this.catalogSequence++;this.generating=false;this.catalogLoading=false;return this.setView('name')}if(this.view==='plan')return this.setView('report');if(this.view==='name')return this.setView('quiz');if(this.view==='quiz'&&this.step>1)return this.previous();if(this.view!=='landing')return this.setView('landing');uni.navigateBack({delta:1,fail:()=>this.setView('landing')})},
  async loadCatalog(){const seq=++this.catalogSequence;this.catalogLoading=true;try{const data=await request('/bootstrap?channel=C');if(seq!==this.catalogSequence||this.disposed)return;if(!Array.isArray(data?.products))throw Error('商品信息暂不可用');this.products=data.products;this.catalogError=''}catch(e){if(seq===this.catalogSequence&&!this.disposed){this.products=[];this.catalogError=e.staleSession?'登录状态已变更，请重新加载商品':e.message}}finally{if(seq===this.catalogSequence)this.catalogLoading=false}},
  openProduct(product){go('product',{id:product.id,channel:'C'})},
  copyReport(){copyText(skincareReportText(this.report),{successText:'护理偏好已复制',onFallback:value=>{this.copyFallback=value}})},
  openConsultation(){
   if(!this.report)return this.start()
   if(!getToken()){
    uni.setStorageSync('shop-skincare-login-handoff',{at:Date.now(),report:this.report});uni.setStorageSync('shop-return',{screen:'skincare',query:{section:'plan'}});go('login');return
   }
   this.consultationOpen=true;this.consultationSent=false;this.contactError='';if(!this.contactAttempt)this.contact={name:this.report.answers.name,phone:'',city:'',consent:false}
  },
  closeConsultation(){if(this.sending)return;this.consultationOpen=false;if(!this.uncertain){this.contact={name:'',phone:'',city:'',consent:false};this.contactAttempt=null}},
  async sendConsultation(){
   if(this.sending||this.consultationSent)return
   if(!getToken()){this.consultationOpen=false;return this.openConsultation()}
   this.contactError=skincareContactError(this.contact);if(this.contactError)return
   const owner=this.owner,token=getToken()
   try{const body=skincareConsultationBody(this.report,this.contact);if(!this.contactAttempt||this.contactAttempt.body!==body)this.contactAttempt={body,imageId:0,orderId:0,requestKey:'skin_chat_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,12)};this.sending=true
    await request('/support/messages','POST',this.contactAttempt)
    if(this.disposed||this.owner!==owner||getToken()!==token)return
    this.consultationSent=true;this.uncertain=false;this.contactAttempt=null;this.contact={name:'',phone:'',city:'',consent:false}
   }catch(e){if(this.disposed||this.owner!==owner)return;this.contactError=e.message;this.uncertain=!!e.uncertain;if(!e.uncertain)this.contactAttempt=null}
   finally{if(this.owner===owner)this.sending=false}
  },
  openSupport(){this.closeConsultation();go('support')}
 }
}
</script>

